const fs = require('fs');
const file = '_worker.js';
let source = fs.readFileSync(file, 'utf8');
const marker = 'bare-product-welcome-conversion-v2';
if (!source.includes(marker)) {
  source += String.raw`

// bare-product-welcome-conversion-v2
const bareProductWelcomeConversionStyle='<style id="bare-product-welcome-conversion-style">.product-welcome-banner{display:block!important;position:relative!important;min-height:210px!important;margin-top:16px!important;border:1px solid #262626!important;background:#0a0a0a!important;box-shadow:0 12px 30px rgba(0,0,0,.12)!important}.product-welcome-banner:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.94) 0%,rgba(0,0,0,.78) 52%,rgba(0,0,0,.2) 100%);pointer-events:none}.product-welcome-banner img{filter:none!important;object-position:65% center!important;transition:transform .35s ease}.product-welcome-banner:hover img{transform:scale(1.025)}.product-welcome-conversion{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:210px;padding:26px 30px;color:#fff}.product-welcome-offer{display:flex;flex-direction:column;align-items:flex-start}.product-welcome-eyebrow{margin-bottom:8px;font-size:10px;font-weight:800;letter-spacing:.18em}.product-welcome-main{font-size:clamp(36px,5vw,58px);font-weight:900;line-height:.86;letter-spacing:-.06em}.product-welcome-shipping{margin-top:10px;font-size:14px;font-weight:800}.product-welcome-note{margin-top:5px;font-size:10px;opacity:.74}.product-welcome-cta{flex:0 0 auto;padding:13px 16px;background:#fff;color:#000;font-size:11px;font-weight:900;letter-spacing:.02em;box-shadow:0 6px 18px rgba(0,0,0,.2);transition:transform .2s ease,background .2s ease}.product-welcome-banner:hover .product-welcome-cta{transform:translateX(3px);background:#f3ff35}@media(max-width:600px){.product-welcome-banner{min-height:178px!important;margin-top:12px!important}.product-welcome-banner:after{background:linear-gradient(90deg,rgba(0,0,0,.95) 0%,rgba(0,0,0,.76) 68%,rgba(0,0,0,.25) 100%)}.product-welcome-banner img{object-position:72% center!important}.product-welcome-conversion{min-height:178px;padding:20px 18px;gap:10px}.product-welcome-main{font-size:36px}.product-welcome-shipping{font-size:12px}.product-welcome-note{font-size:9px}.product-welcome-cta{padding:11px 12px;font-size:10px}}</style>';
const bareProductWelcomeConversionScript='<script id="bare-product-welcome-conversion-script">(()=>{const html="<img src=\\"https://shop-phinf.pstatic.net/20260514_299/17787381562510SFCd_JPEG/57535494600578401_1343151862.jpg?type=o1000\\" alt=\\"\\"><span class=\\"product-welcome-conversion\\"><span class=\\"product-welcome-offer\\"><span class=\\"product-welcome-eyebrow\\">NEW MEMBER WELCOME PACK</span><strong class=\\"product-welcome-main\\">10% OFF</strong><span class=\\"product-welcome-shipping\\">첫 구매 무료배송까지</span><span class=\\"product-welcome-note\\">가입 즉시 자동 적용</span></span><span class=\\"product-welcome-cta\\">웰컴팩 받기 →</span></span>";let timer=0;function sync(){document.querySelectorAll(".product-detail .product-welcome-banner").forEach(el=>{if(el.dataset.welcomeRedesign==="v2")return;el.innerHTML=html;el.dataset.welcomeRedesign="v2";el.setAttribute("aria-label","가입하고 첫 구매 10% 할인과 무료배송 받기")})}function queue(){clearTimeout(timer);timer=setTimeout(sync,40)}new MutationObserver(queue).observe(document.body,{childList:true,subtree:true});addEventListener("hashchange",queue);queue()})();</script>';
const bareProductWelcomeConversionBase=patchHtml;
patchHtml=function(html){return bareProductWelcomeConversionBase(html).replace('</head>',bareProductWelcomeConversionStyle+'</head>').replace('</body>',bareProductWelcomeConversionScript+'</body>')};
`;
  fs.writeFileSync(file, source);
}
for (const path of ['.github/redesign-product-welcome-banner.cjs', '.github/workflows/redesign-product-welcome-banner.yml']) {
  try { fs.unlinkSync(path); } catch (_) {}
}
